apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: {{ingress_name}}
  namespace: {{namespace}}
  annotations:
    cert-manager.io/cluster-issuer: {{cluster_issuer}}
    nginx.ingress.kubernetes.io/ssl-redirect: "true"
spec:
  ingressClassName: nginx
  tls:
    - hosts:
        - {{host}}
      secretName: {{tls_secret_name}}
  rules:
    - host: {{host}}
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{service_name}}
                port:
                  number: {{service_port}}
